//                             In The Name Of Allah                                           
//                             	Mohammad Hosseini
#include <iostream>
#include <vector>
#include <cstring>
#include <algorithm>
using namespace std;

using i64 = long long;
using PII = pair<i64, i64>;

const i64 MOD = 1000000007LL;
const int MAX_D = 64, MAX_LG = 65;

i64 n_val, d_val;
vector<i64> digit_list;

struct MatrixNode {
    i64 mat[MAX_D][MAX_D], buf[MAX_D][MAX_D];
    bool flag[MAX_D], tmp[MAX_D];

    void combine(const MatrixNode& other) {
        memset(buf, 0, sizeof(buf));
        for (int i = 0; i <= d_val; ++i) {
            for (int j = 0; j <= d_val; ++j) {
                for (int k = 0; k <= d_val; ++k) {
                    buf[i][j] = (buf[i][j] + mat[k][j] * other.mat[i][k]) % MOD;
                }
            }
        }
        for (int i = 0; i < d_val; ++i) {
            if (flag[i] && !other.flag[i]) {
                for (int j = 0; j <= d_val; ++j)
                    buf[i][j] = mat[i][j];
            }
            if (!flag[i] && other.flag[i]) {
                for (int j = 0; j <= d_val; ++j)
                    buf[j][i] = other.mat[j][i];
            }
            flag[i] |= other.flag[i];
        }
        memcpy(mat, buf, sizeof(mat));
    }

    void zeroize() {
        memset(mat, 0, sizeof(mat));
        memset(buf, 0, sizeof(buf));
    }

    void rotate(int shift_amount) {
        memset(buf, 0, sizeof(buf));
        for (int i = 0; i < d_val; ++i) {
            for (int j = 0; j < d_val; ++j) {
                buf[(i + shift_amount) % d_val][(j + shift_amount) % d_val] = mat[i][j];
            }
            buf[(i + shift_amount) % d_val][d_val] = mat[i][d_val];
        }
        for (int i = 0; i < d_val; ++i) {
            buf[d_val][(i + shift_amount) % d_val] = mat[d_val][i];
        }
        buf[d_val][d_val] = mat[d_val][d_val];
        memcpy(mat, buf, sizeof(mat));
        for (int i = 0; i < d_val; ++i) {
            tmp[i] = flag[(i + shift_amount) % d_val];
        }
        memcpy(flag, tmp, sizeof(flag));
    }
} seg_tree[MAX_LG], pref_tree[MAX_LG], work_node;

MatrixNode compute_node(i64 x) {
    i64 block = x, block_size = 1, depth = -1;
    while (block >= d_val) {
        block /= d_val;
        block_size *= d_val;
        ++depth;
    }
    x %= block_size;
    if (depth == -1) return pref_tree[block];
    MatrixNode res = seg_tree[depth];
    work_node = seg_tree[depth];
    for (int step = 1; step < block; ++step) {
        work_node.rotate(1);
        res.combine(work_node);
    }
    work_node = compute_node(x);
    work_node.rotate(block);
    res.combine(work_node);
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n_val >> d_val;
    --n_val;
    i64 orig = n_val;
    while (n_val > 0) {
        digit_list.push_back(n_val % d_val);
        n_val /= d_val;
    }

    pref_tree[0].mat[d_val][d_val] = 2;
    pref_tree[0].mat[d_val][0] = -1;
    pref_tree[0].mat[0][d_val] = 1;
    pref_tree[0].flag[0] = true;
    seg_tree[0] = pref_tree[0];

    for (int idx = 1; idx < d_val; ++idx) {
        pref_tree[idx].mat[d_val][d_val] = 2;
        pref_tree[idx].mat[d_val][idx] = -1;
        pref_tree[idx].mat[idx][d_val] = 1;
        pref_tree[idx].flag[idx] = true;
        seg_tree[0].combine(pref_tree[idx]);
        pref_tree[idx] = seg_tree[0];
    }

    for (int lvl = 1; lvl <= (int)digit_list.size(); ++lvl) {
        seg_tree[lvl] = seg_tree[lvl - 1];
        work_node = seg_tree[lvl - 1];
        for (int j = 1; j < d_val; ++j) {
            work_node.rotate(1);
            seg_tree[lvl].combine(work_node);
        }
    }

    MatrixNode final_result = compute_node(orig);
    cout << final_result.mat[d_val][d_val] << '\n';

    return 0;
}
